import{_ as a,o as l,c as n,a2 as s}from"./chunks/framework.BXzK3EA4.js";const e="/assets/720eaa1739931b35.CnEb0pNX.png",_=JSON.parse('{"title":"Linux系统宝塔面板安装教程","description":"","frontmatter":{"title":"Linux系统宝塔面板安装教程"},"headers":[],"relativePath":"ops-knowledge-base/operating-system/linux/install-baota-panel.md","filePath":"ops-knowledge-base/operating-system/linux/install-baota-panel.md","lastUpdated":1788259091000}'),p={name:"ops-knowledge-base/operating-system/linux/install-baota-panel.md"};function r(i,t,o,h,b,d){return l(),n("div",null,[...t[0]||(t[0]=[s('<p>一、安装要求：</p><p>1.内存：512M以上，推荐768M以上（纯面板约占系统60M内存）</p><p>2.硬盘：300M以上可用硬盘空间（纯面板约占20M磁盘空间）</p><p>3.系统：CentOS 7.1+ (Ubuntu16.04+、Debian9.0+)，确保是干净的操作系统，没有安装过其它环境带的Apache/Nginx/php/MySQL/pgsql/gitlab/java（已有环境不可安装</p><p>4.架构：x86_64</p><p>5.宝塔linux7.0版本是基于centos7开发的，务必使用centos7.x 系统 提示：Centos官方已宣布在2020年停止对Centos6的维护更新，各大软件开发商也逐渐停止对Centos6的兼容，新服务器不建议使用Centos6</p><p>二、宝塔Linux面板7.9.0安装方法：</p><ol><li>CentOS 8官方已经停止支持、请更换CentOS7系统或CentOS 8 Stream系统安装宝塔，详细说明：<a href="https://www.bt.cn/bbs/thread-82931-1-1.html" target="_blank" rel="noreferrer">Centos 8升级至Centos 8 Stream教程 - Linux面板 - 宝塔面板论坛 (bt.cn)</a></li></ol><p>1.CentOS安装命令：</p><p>Yum install -y wget &amp;&amp; wget -O install.sh <a href="https://download.bt.cn/install/install%5C_6.0.sh" target="_blank" rel="noreferrer">https://download.bt.cn/install/install\\_6.0.sh</a> &amp;&amp; sh install.sh 12f2c1d72</p><p>2.Ubuntu/Deepin安装命令：</p><p>wget -O install.sh <a href="https://download.bt.cn/install/install-ubuntu%5C_6.0.sh" target="_blank" rel="noreferrer">https://download.bt.cn/install/install-ubuntu\\_6.0.sh</a> &amp;&amp; sudo bash install.sh 12f2c1d72</p><p>3.Debian安装命令：</p><p>wget -O install.sh <a href="https://download.bt.cn/install/install-ubuntu%5C_6.0.sh" target="_blank" rel="noreferrer">https://download.bt.cn/install/install-ubuntu\\_6.0.sh</a> &amp;&amp; bash install.sh 12f2c1d72</p><p>4.Fedora安装命令：</p><p>wget -O install.sh <a href="https://download.bt.cn/install/install%5C_6.0.sh" target="_blank" rel="noreferrer">https://download.bt.cn/install/install\\_6.0.sh</a> &amp;&amp; bash install.sh 12f2c1d72</p><p>5.Linux面板升级7.9.8命令：</p><p>curl <a href="https://download.bt.cn/install/update%5C_panel.sh%7Cbash" target="_blank" rel="noreferrer">https://download.bt.cn/install/update\\_panel.sh|bash</a></p><p>三、以上节点如果无法使用，请使用下面的备用节点安装：</p><p>1.备用节点广东：</p><p>yum install –y wget &amp;&amp; wget –O install.sh <a href="http://125.88.182.172:5880/install/install" target="_blank" rel="noreferrer">http://125.88.182.172:5880/install/install</a> 6.0.sh &amp;&amp; sh install.sh</p><p>2.备用节点香港：</p><p>yum install –y wget &amp;&amp; wget –O install.sh <a href="http://103.224.251.67:5880/install/install" target="_blank" rel="noreferrer">http://103.224.251.67:5880/install/install</a> 6.0sh &amp;&amp; sh install.sh</p><p>3.备用节点美国：</p><p>Yum install –y wget &amp;&amp; wget –O install.sh <a href="http://128.1.164.196:5880/install/install" target="_blank" rel="noreferrer">http://128.1.164.196:5880/install/install</a> 6.0.sh &amp;&amp; sh install.sh</p><p>使用SSH连接工具，如xshell、putty连接到您的Linux服务器后，根据系统执行相应的命令开始安装（大约2分钟完成面板安装），安装完成后会提示登录信息，如您需要更改密码、重启宝塔、修改端口、卸载宝塔等操作，可以直接输入：bt就会显示出对应的操作选项，如下图所示，根据提示完成操作即可。</p><p><img src="'+e+'" alt=""></p><p>四、Linux面板7.9.8更新功能：</p><p>1.增加登录表单数据的RSA加密验证机制</p><p>2.增加敏感数据（用户名、密码等）的加密存储机制</p><p>3.优化关键数据传输加密机制及会话绑定机制，防止重放攻击</p><p>4.同步部分测试版已验证的Bug修复</p>',32)])])}const u=a(p,[["render",r]]);export{_ as __pageData,u as default};
